  LinearLayout root,inputs; RigView rig; TextView status,result,levelText; Spinner loadCase,viewMode,qProfile,faultMode; EditText L,D,F,M,stations,layers,actCount,actCapacity,pressure,sf,padW,padL,deflection,linkLength,beamSpan,beamH,beamB,pinAllow,bearingAllow; SeekBar level;
  String[] CASES={"+Z Bending","-Z Bending","+Y Bending","-Y Bending","Pitch +My","Pitch -My","Roll +Mx","Roll -Mx","Yaw +Mz","Yaw -Mz","Combined Z+Pitch"};
