  Spinner spin(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
  EditText field(String label,String def){inputs.addView(tx(label,12,true,Color.rgb(185,210,230)));EditText e=new EditText(this);e.setText(def);e.setTextColor(Color.WHITE);e.setTextSize(16);e.setSingleLine(true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);e.setBackground(bg(Color.rgb(25,52,75),8));e.setPadding(dp(10),0,dp(10),0);inputs.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
  void safe(){try{preview(compute(false));}catch(Exception ignored){}}
  void preview(Calc c){rig.set(c,loadCase.getSelectedItemPosition(),viewMode.getSelectedItemPosition(),level.getProgress()/100.0,faultMode.getSelectedItemPosition());status.setText(String.format(Locale.US,"%s • %s • S%d L%d A%d • %.0f%% load",CASES[loadCase.getSelectedItemPosition()],VIEWS[viewMode.getSelectedItemPosition()],c.n,c.layers,c.nAct,level.getProgress()*1.0));}
  void calculate(){try{Calc c=compute(false);preview(c);StringBuilder s=new StringBuilder();s.append("EFT ENGINEERING SUMMARY\n\n");s.append(String.format(Locale.US,"Case: %s\nStations %d | Layers %d | Actuators %d\nΣF %.1f kN | M %.1f kN·m | M error %.2f%%\n\n",CASES[loadCase.getSelectedItemPosition()],c.n,c.layers,c.nAct,c.sumF,c.calcM,c.mErr));s.append(String.format(Locale.US,"Actuator demand %.1f kN | bore %.1f mm @ %.0f bar\nLoad cell ≥ %.0f kN\nStroke %.1f mm | link angle %.1f°\nBeam σ %.1f MPa | Pin Ø%.0f mm | Pad %.2f MPa\n\n",c.actLoad,c.bore,c.pbar,c.lc,c.strokeReq,c.linkAngle,c.beamStress,c.pinSel,c.padPressure));s.append("TEST MATRIX\n").append(c.testMatrix).append("\nFAULT STATUS\n").append(faultSummary(c)).append("\nGATES\n").append(c.gates).append("\nBOM\n").append(c.bom);result.setText(s.toString());}catch(Exception e){result.setText("Girişleri kontrol et.");}}

  Calc compute(boolean opt){Calc c=new Calc();c.L=Math.max(.5,d(L));c.D=Math.max(.1,d(D));c.targetF=Math.abs(d(F));c.targetM=d(M);c.n=clamp((int)Math.round(d(stations)),4,16);c.layers=clamp((int)Math.round(d(layers)),1,3);double cap=Math.max(1,d(actCapacity));c.pbar=Math.max(1,d(pressure));c.sf=Math.max(1,d(sf));c.designF=c.targetF*c.sf;int manual=clamp((int)Math.round(d(actCount)),1,8);int minCap=(int)Math.ceil(c.designF/cap);int minTopo=Math.max(1,(int)Math.ceil(c.n/Math.pow(2,c.layers)));c.nAct=opt?clamp(Math.max(minCap,minTopo),1,8):manual;c.actLoad=c.designF/c.nAct;c.bore=Math.sqrt(4*(c.actLoad*1000)/(c.pbar*100000)/Math.PI)*1000;c.lc=std(c.actLoad*1.2);
    c.x=new double[c.n];c.fi=new double[c.n];double[] w=new double[c.n];double sw=0;int q=qProfile.getSelectedItemPosition();for(int i=0;i<c.n;i++){double u=(i+.5)/c.n;c.x[i]=u*c.L;if(q==0)w[i]=Math.sqrt(Math.max(0,1-Math.pow(2*u-1,2)))+.05;else if(q==1)w[i]=1;else if(q==2)w[i]=1.15-u;else if(q==3)w[i]=.15+u;else w[i]=.25+4*u*(1-u);sw+=w[i];}for(int i=0;i<c.n;i++)c.fi[i]=c.targetF*w[i]/sw;
    double desired=Math.abs(c.targetM),base=0;for(int i=0;i<c.n;i++)base+=c.fi[i]*c.x[i];double mean=0;for(double xx:c.x)mean+=xx;mean/=c.n;double den=0;for(double xx:c.x)den+=(xx-mean)*(xx-mean);double delta=desired-base;if(Math.abs(delta)>1e-9&&den>1e-9)for(int i=0;i<c.n;i++)c.fi[i]+=delta*(c.x[i]-mean)/den;boolean neg=false;for(double v:c.fi)if(v<0)neg=true;if(neg){for(int i=0;i<c.n;i++)c.fi[i]=Math.max(.001,c.fi[i]);double ss=0;for(double v:c.fi)ss+=v;for(int i=0;i<c.n;i++)c.fi[i]*=c.targetF/ss;}c.sumF=0;c.calcM=0;for(int i=0;i<c.n;i++){c.sumF+=c.fi[i];c.calcM+=c.fi[i]*c.x[i];}if(c.targetM<0)c.calcM=-c.calcM;c.mErr=Math.abs(c.targetM)>1e-6?100*(c.calcM-c.targetM)/Math.abs(c.targetM):0;
    int branch=c.n,beams=0;for(int l=0;l<c.layers&&branch>1;l++){beams+=branch/2;branch=(branch+1)/2;}c.beams=beams;c.topBranches=branch;c.tree=synth(c);c.bom=bom(c);
    double def=Math.max(0,d(deflection)),link=Math.max(50,d(linkLength));c.strokeReq=def*1.25+20;c.linkAngle=Math.toDegrees(Math.atan2(def,link));c.sideLoad=c.actLoad*Math.sin(Math.toRadians(c.linkAngle));double maxFi=0;for(double f:c.fi)maxFi=Math.max(maxFi,f);c.padArea=Math.max(1,d(padW)*d(padL));c.padPressure=maxFi*1000/(c.padArea/1e6)/1e6;
    double span=Math.max(100,d(beamSpan))/1000.0,bh=Math.max(10,d(beamH))/1000.0,bb=Math.max(10,d(beamB))/1000.0;double Fbeam=Math.max(maxFi*c.sf,c.actLoad)*1000;c.beamM=Fbeam*span/4/1000.0;double I=bb*Math.pow(bh,3)/12;c.beamStress=(c.beamM*1000*(bh/2)/I)/1e6;c.beamDefl=(Fbeam*Math.pow(span,3)/(48*70e9*I))*1000;
    double tauAllow=Math.max(20,d(pinAllow))*1e6;c.pinReq=Math.sqrt(2*Fbeam/(Math.PI*tauAllow))*1000;c.pinSel=Math.ceil(c.pinReq/2.0)*2.0;double bear=Math.max(20,d(bearingAllow))*1e6;c.lugT=(Fbeam/(bear*(c.pinSel/1000.0)))*1000;c.gates=gates(c,cap);c.testMatrix=testMatrix(c);return c;}

  String synth(Calc c){StringBuilder sb=new StringBuilder();ArrayList<Double> vals=new ArrayList<>();for(double f:c.fi)vals.add(f*c.sf);for(int lev=1;lev<=c.layers&&vals.size()>1;lev++){ArrayList<Double> nx=new ArrayList<>();sb.append("Layer ").append(lev).append(":\n");for(int i=0;i<vals.size();i+=2){if(i+1<vals.size()){double a=vals.get(i),b=vals.get(i+1),sum=a+b;sb.append(String.format(Locale.US," B%d %.1f+%.1f=%.1f kN pivot %.0f/%.0f%%\n",i/2+1,a,b,sum,100*b/sum,100*a/sum));nx.add(sum);}else nx.add(vals.get(i));}vals=nx;}return sb.toString();}
  String bom(Calc c){int piv=c.beams*3,links=c.n+Math.max(0,c.beams-c.topBranches),anchors=Math.max(4,c.nAct*2);return "Actuator: "+c.nAct+" ea\nLoad cell: "+c.nAct+" ea ≥"+fmt(c.lc)+" kN\nServo valve: "+c.nAct+" ea\nSpherical bearing: "+c.nAct+" ea\nWhiffletree beam: "+c.beams+" ea\nPivot/pin set: "+piv+" sets\nTie rod/link: "+links+" ea\nStation rod-end: "+c.n+" ea\nClevis: "+(c.n+c.nAct)+" ea\nLoad pad/saddle: "+c.n+" ea\nHydraulic hose pair: "+c.nAct+" sets\nHP manifold: 1 set\nPressure transducer: 1 ch\nLVDT/position: "+c.nAct+" ch\nForce DAQ: "+c.nAct+" ch\nEmergency dump valve: 1 set\nStrongback: 1 assembly\nFloor anchor: "+anchors+" ea";}
  String gates(Calc c,double cap){StringBuilder s=new StringBuilder();s.append(Math.abs(c.mErr)<=1?"PASS":"WARN").append(" force/moment equivalence\n");s.append(c.actLoad<=cap?"PASS":"FAIL").append(" actuator capacity\n");s.append(c.linkAngle<=6?"PASS":"WARN").append(" link angle\n");s.append(c.beamStress<180?"PASS":"REVIEW").append(" beam training stress\n");s.append(c.padPressure<8?"PASS":"REVIEW").append(" pad mean pressure\n");s.append(c.strokeReq<=120?"PASS":"WARN").append(" stroke envelope\n");return s.toString();}
  String testMatrix(Calc c){int[] lv={0,10,25,50,75,100};StringBuilder s=new StringBuilder();for(int x:lv){double k=x/100.0;double f=c.sumF*k,m=c.calcM*k,stroke=c.strokeReq*k;String st=(stroke>120||c.actLoad*k>d(actCapacity))?"WARN":"PASS";s.append(String.format(Locale.US,"%3d%%  F=%7.1f kN  M=%8.1f kN·m  stroke=%5.1f mm  %s\n",x,f,m,stroke,st));}return s.toString();}
  String faultSummary(Calc c){int f=faultMode.getSelectedItemPosition();if(f==0)return "No fault injected.";if(f==1)return String.format(Locale.US,"LC1 reads +5%%: commanded %.1f kN, indicated %.1f kN. Check calibration/channel balance.",c.actLoad,c.actLoad*1.05);if(f==2)return String.format(Locale.US,"Stroke limit scenario: required %.1f mm. If actuator limit is 120 mm, %s.",c.strokeReq,c.strokeReq>120?"ABORT":"margin remains");if(f==3)return String.format(Locale.US,"Pad overload scenario: mean peak %.2f MPa; local FEM/contact review required.",c.padPressure*1.35);if(f==4)return String.format(Locale.US,"Beam overload scenario: stress rises to %.1f MPa.",c.beamStress*1.30);return "Channel mismatch scenario: A1 +6%, A2 -4%; verify cross-channel disagreement trip.";}

  class RigView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG);Calc c;int ci,mode,fault;double lf;RigView(){super(MainActivity.this);setBackgroundColor(Color.rgb(4,15,27));t.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));}void set(Calc x,int cidx,int m,double l,int f){c=x;ci=cidx;mode=m;lf=l;fault=f;invalidate();}protected void onDraw(Canvas cn){super.onDraw(cn);if(c==null)return;if(mode<=2)drawArticle(cn);else if(mode==3)drawTree(cn,false);else if(mode==4)drawTree(cn,true);else if(mode==5)drawBeam(cn);else if(mode==6)drawPin(cn);else if(mode==7)drawHyd(cn);else if(mode==8)drawBom(cn);else if(mode==9)drawTest(cn);else if(mode==10)drawFault(cn);else drawValidation(cn);}
    void title(Canvas cn,String s){t.setColor(Color.WHITE);t.setTextSize(dp(14));cn.drawText(s,dp(12),dp(24),t);t.setTextSize(dp(10));t.setColor(Color.rgb(190,210,225));cn.drawText("Case "+CASES[ci]+" | L"+c.layers+" | A"+c.nAct+" | load "+(int)(lf*100)+"%",dp(12),dp(42),t);}
    void drawTank(Canvas cn,float left,float right,float y){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(48,60,73));cn.drawRoundRect(new RectF(left,y-dp(24),right,y+dp(24)),dp(24),dp(24),p);p.setStyle(Paint.Style.STROKE);p.setColor(STEEL);p.setStrokeWidth(2);cn.drawRoundRect(new RectF(left,y-dp(24),right,y+dp(24)),dp(24),dp(24),p);}
    void arrow(Canvas cn,float x,float y,float dx,float dy,int color){p.setColor(color);p.setStrokeWidth(4);cn.drawLine(x,y,x+dx,y+dy,p);double a=Math.atan2(dy,dx);float ex=x+dx,ey=y+dy;cn.drawLine(ex,ey,ex-(float)(12*Math.cos(a-.55)),ey-(float)(12*Math.sin(a-.55)),p);cn.drawLine(ex,ey,ex-(float)(12*Math.cos(a+.55)),ey-(float)(12*Math.sin(a+.55)),p);}
    void drawArticle(Canvas cn){title(cn,VIEWS[mode]);int w=getWidth(),h=getHeight();float left=w*.08f,right=w*.94f,y=h*.38f;if(mode==2){float cx=w*.5f,rad=Math.min(w*.22f,h*.13f);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(48,60,73));cn.drawCircle(cx,y,rad,p);p.setStyle(Paint.Style.STROKE);p.setColor(STEEL);p.setStrokeWidth(2);cn.drawCircle(cx,y,rad,p);for(int i=0;i<8;i++){double a=2*Math.PI*i/8;float x=cx+(float)Math.cos(a)*rad,y1=y+(float)Math.sin(a)*rad;arrow(cn,x,y1,(float)Math.cos(a)*dp(42)*(float)lf,(float)Math.sin(a)*dp(42)*(float)lf,BLUE);}return;}drawTank(cn,left,right,y);for(int i=0;i<c.n;i++){float x=left+(float)(c.x[i]/c.L)*(right-left);p.setColor(CYAN);p.setStrokeWidth(1);cn.drawLine(x,y-dp(25),x,y+dp(25),p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("S"+(i+1),x-dp(7),y+dp(42),t);double f=c.fi[i]*lf;float mag=dp(20)+(float)Math.min(dp(60),f*.8);if(mode==0){boolean up=ci!=1&&ci!=3;arrow(cn,x,y-dp(28),0,up?-mag:mag,BLUE);}else{boolean rr=ci!=3&&ci!=9;arrow(cn,x,y,rr?mag:-mag,0,ORANGE);}}dimension(cn,left,right,y+dp(90),String.format(Locale.US,"L = %.2f m",c.L));}
    void dimension(Canvas cn,float a,float b,float y,String s){p.setColor(STEEL);p.setStrokeWidth(1);cn.drawLine(a,y,b,y,p);cn.drawLine(a,y-dp(5),a,y+dp(5),p);cn.drawLine(b,y-dp(5),b,y+dp(5),p);t.setColor(Color.WHITE);t.setTextSize(dp(9));cn.drawText(s,(a+b)/2-dp(28),y-dp(6),t);}
    ArrayList<float[]> baseNodes(float left,float right,float y){ArrayList<float[]> n=new ArrayList<>();for(int i=0;i<c.n;i++){float x=left+(float)(c.x[i]/c.L)*(right-left);n.add(new float[]{x,y,(float)(c.fi[i]*c.sf*lf)});}return n;}
    void drawTree(Canvas cn,boolean mech){title(cn,mech?"Mechanical load path":"Symbolic whiffletree");int w=getWidth(),h=getHeight();float left=w*.06f,right=w*.95f,tankY=dp(100);drawTank(cn,left,right,tankY);ArrayList<float[]> nodes=baseNodes(left,right,tankY+dp(30));float base=tankY+dp(78);for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++){ArrayList<float[]> nx=new ArrayList<>();float yy=base+dp(62)*(lev-1);p.setColor(lev==1?ORANGE:(lev==2?YELLOW:CYAN));p.setStrokeWidth(mech?7:4);for(int i=0;i<nodes.size();i+=2){if(i+1<nodes.size()){float[]a=nodes.get(i),b=nodes.get(i+1);float sum=a[2]+b[2],px=sum>0?(a[0]*b[2]+b[0]*a[2])/sum:(a[0]+b[0])/2;cn.drawLine(a[0],yy,b[0],yy,p);p.setStrokeWidth(2);cn.drawLine(a[0],a[1],a[0],yy,p);cn.drawLine(b[0],b[1],b[0],yy,p);p.setStyle(Paint.Style.FILL);cn.drawCircle(px,yy,dp(5),p);p.setStyle(Paint.Style.STROKE);nx.add(new float[]{px,yy,sum});}else nx.add(nodes.get(i));}nodes=nx;}float ay=Math.min(h-dp(110),base+dp(62)*c.layers+dp(25));for(int a=0;a<c.nAct;a++){float x=w*(a+1f)/(c.nAct+1f);p.setStyle(Paint.Style.FILL);p.setColor(mech?Color.rgb(80,95,110):GREEN);cn.drawRoundRect(new RectF(x-dp(16),ay-dp(42),x+dp(16),ay),dp(5),dp(5),p);if(mech){p.setColor(RED);cn.drawRect(x-dp(14),ay-dp(60),x+dp(14),ay-dp(46),p);p.setColor(YELLOW);cn.drawCircle(x,ay-dp(70),dp(7),p);}p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);float tx=nodes.get(Math.min(a,nodes.size()-1))[0],ty=nodes.get(Math.min(a,nodes.size()-1))[1];cn.drawLine(x,ay-dp(42),tx,ty,p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("A"+(a+1),x-dp(7),ay+dp(16),t);} }
    void drawBeam(Canvas cn){title(cn,"Whiffletree beam detail");int w=getWidth(),h=getHeight();float x1=w*.15f,x2=w*.85f,y=h*.36f;p.setColor(ORANGE);p.setStrokeWidth(dp(12));cn.drawLine(x1,y,x2,y,p);p.setColor(YELLOW);p.setStyle(Paint.Style.FILL);cn.drawCircle((x1+x2)/2,y,dp(8),p);arrow(cn,x1,y-dp(5),0,dp(70),BLUE);arrow(cn,x2,y-dp(5),0,dp(70),BLUE);dimension(cn,x1,x2,y+dp(110),String.format(Locale.US,"span %.0f mm",d(beamSpan)));textBlock(cn,new String[]{String.format(Locale.US,"Mmax %.2f kN·m",c.beamM),String.format(Locale.US,"Stress %.1f MPa",c.beamStress),String.format(Locale.US,"Deflection %.2f mm",c.beamDefl)},dp(20),h*.62f);}
    void drawPin(Canvas cn){title(cn,"Pin / Clevis detail");int w=getWidth(),h=getHeight();float cx=w*.5f,cy=h*.33f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(12));p.setColor(STEEL);cn.drawLine(cx-dp(70),cy-dp(80),cx-dp(70),cy+dp(80),p);cn.drawLine(cx+dp(70),cy-dp(80),cx+dp(70),cy+dp(80),p);p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);cn.drawRect(cx-dp(60),cy-dp(30),cx+dp(60),cy+dp(30),p);p.setColor(YELLOW);cn.drawCircle(cx,cy,dp(18),p);textBlock(cn,new String[]{String.format(Locale.US,"Required pin %.1f mm",c.pinReq),String.format(Locale.US,"Selected schematic Ø%.0f mm",c.pinSel),String.format(Locale.US,"Lug t min %.1f mm",c.lugT)},dp(20),h*.62f);}
    void drawHyd(Canvas cn){title(cn,"Hydraulic architecture");int h=getHeight();float y=dp(120);box(cn,dp(20),y,dp(90),dp(55),"HPU");box(cn,dp(135),y,dp(100),dp(55),"Manifold");box(cn,dp(260),y,dp(105),dp(55),"Dump/relief");float sy=y+dp(110);for(int a=0;a<c.nAct;a++){float yy=sy+a*dp(48);box(cn,dp(55),yy,dp(110),dp(34),"SV"+(a+1));box(cn,dp(205),yy,dp(125),dp(34),"ACT"+(a+1));p.setColor(CYAN);p.setStrokeWidth(3);cn.drawLine(dp(165),yy+dp(17),dp(205),yy+dp(17),p);} }
    void box(Canvas cn,float x,float y,float ww,float hh,String s){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(40,63,82));cn.drawRoundRect(new RectF(x,y,x+ww,y+hh),dp(6),dp(6),p);p.setStyle(Paint.Style.STROKE);p.setColor(STEEL);p.setStrokeWidth(2);cn.drawRoundRect(new RectF(x,y,x+ww,y+hh),dp(6),dp(6),p);t.setColor(Color.WHITE);t.setTextSize(dp(9));cn.drawText(s,x+dp(8),y+hh/2+dp(4),t);}
    void drawBom(Canvas cn){title(cn,"Dynamic BOM");textBlock(cn,c.bom.split("\\n"),dp(18),dp(75));}
    void drawTest(Canvas cn){title(cn,"Test Run — staged loading");int[] lv={0,10,25,50,75,100};float y=dp(95),w=getWidth();for(int i=0;i<lv.length;i++){float yy=y+i*dp(70);double k=lv[i]/100.0;boolean warn=c.strokeReq*k>120||c.actLoad*k>d(actCapacity);p.setStyle(Paint.Style.FILL);p.setColor(warn?RED:GREEN);cn.drawRoundRect(new RectF(dp(18),yy,w-dp(18),yy+dp(48)),dp(8),dp(8),p);t.setColor(Color.WHITE);t.setTextSize(dp(10));cn.drawText(String.format(Locale.US,"%3d%%   F %.1f kN   M %.1f kN·m   stroke %.1f mm   %s",lv[i],c.sumF*k,c.calcM*k,c.strokeReq*k,warn?"WARN":"PASS"),dp(28),yy+dp(30),t);} }
    void drawFault(Canvas cn){title(cn,"Fault Injection");String f=faultSummary(c);int w=getWidth(),h=getHeight();drawTree(cn,true);p.setStyle(Paint.Style.FILL);p.setColor(fault==0?GREEN:RED);cn.drawRoundRect(new RectF(dp(18),h-dp(110),w-dp(18),h-dp(30)),dp(8),dp(8),p);t.setColor(Color.WHITE);t.setTextSize(dp(10));wrap(cn,f,dp(28),h-dp(82),w-dp(56));}
    void drawValidation(Canvas cn){title(cn,"Validation Matrix");String[] ls=c.gates.split("\\n");float y=dp(90);for(String s:ls){if(s.length()==0)continue;boolean pass=s.startsWith("PASS"),fail=s.startsWith("FAIL");p.setStyle(Paint.Style.FILL);p.setColor(pass?GREEN:(fail?RED:YELLOW));cn.drawRoundRect(new RectF(dp(18),y,getWidth()-dp(18),y+dp(50)),dp(8),dp(8),p);t.setColor(Color.WHITE);t.setTextSize(dp(10));cn.drawText(s,dp(28),y+dp(30),t);y+=dp(64);} }
    void textBlock(Canvas cn,String[] lines,float x,float y){t.setColor(Color.WHITE);t.setTextSize(dp(10));for(String s:lines){cn.drawText(s,x,y,t);y+=dp(28);}}
    void wrap(Canvas cn,String s,float x,float y,float max){String[] w=s.split(" ");String line="";for(String q:w){String test=line.length()==0?q:line+" "+q;if(t.measureText(test)>max){cn.drawText(line,x,y,t);y+=dp(22);line=q;}else line=test;}if(line.length()>0)cn.drawText(line,x,y,t);}
  }

  static class Calc{double L,D,targetF,targetM,pbar,sf,designF,actLoad,bore,lc,sumF,calcM,mErr,strokeReq,linkAngle,sideLoad,padArea,padPressure,beamM,beamStress,beamDefl,pinReq,pinSel,lugT;int n,layers,nAct,beams,topBranches;double[]x,fi;String tree,bom,gates,testMatrix;}
  double std(double v){double[]a={10,20,25,50,75,100,150,200,250,300,500,750,1000};for(double x:a)if(x>=v)return x;return Math.ceil(v/100)*100;}double d(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}String fmt(double v){return String.format(Locale.US,"%.1f",v);}int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}TextView tx(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;}TextView card(String s,int c){TextView v=tx(s,13,false,Color.WHITE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(bg(c,10));return v;}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
